 IF exists(select 1 from supabase_migrations.schema_migrations where name='concierge_no_current_products') THEN RAISE EXCEPTION 'NoProducts ledger already present; reconcile rather than repeat'; END IF;
 IF (select count(*) from supabase_migrations.schema_migrations)<>75 THEN RAISE EXCEPTION 'Unexpected migration ledger count'; END IF;
 IF (select count(*) from supabase_migrations.schema_migrations where (version,name) in (('20261025030725','concierge_founder_admission'),('20261025030747','concierge_checkin_replies'),('20261025030748','concierge_manual_payment_methods')))<>3 THEN RAISE EXCEPTION 'Prerequisite ledger mismatch'; END IF;
